/*
Product vision, requirements, architecture direction and delivery leadership: Andrews Mensah.
AI-assisted implementation developed under his direction.
*/
import {money} from './engine.mjs';
const app=document.querySelector('#app');let user=null,csrf='',catalog=[],model={},policy={},workspace={patients:[],plans:[],quotes:[],finance:[],payments:[]},busy=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const can=(...roles)=>roles.includes(user?.role);
const title=(t,s)=>`<h1>${t}</h1><p class="sub">${s}</p>`;
const pill=(s,w=false)=>`<span class="pill ${w?'warn':''}">${esc(s)}</span>`;
const patient=id=>workspace.patients.find(p=>p.id===id)?.reference||id;
const family=code=>catalog.find(c=>c.code===code)?.name||code;
const opts=(items,value,label)=>items.map(i=>`<option value="${esc(value(i))}">${esc(label(i))}</option>`).join('');
const field=(label,input)=>`<div class="field"><label>${label}${input}</label></div>`;
const cents=s=>{if(!/^\d{1,7}(\.\d{1,2})?$/.test(s))throw Error('Enter dollars with at most two decimals');const [w,f='']=s.split('.');return Number(w)*100+Number(f.padEnd(2,'0'));};
function toast(message,error=false){const e=document.querySelector('#toast');e.textContent=message;e.className=error?'error':'';e.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.hidden=true,6000);}
async function api(path,body,method=body===undefined?'GET':'POST'){
 const key=crypto.randomUUID();const request={method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,'Idempotency-Key':key},credentials:'same-origin',...(body!==undefined?{body:JSON.stringify(body)}:{})};
 let response;try{response=await fetch(path,request);}catch{response=await fetch(path,request);}
 let data;try{data=await response.json();}catch{throw Error('Server returned an unreadable response');}
 if(!response.ok){if(response.status===401){user=null;render();}throw Error(data.error||`Request failed (${response.status})`);}return data;
}
function login(){return `<section class="panel login"><h1>Welcome to Clarity</h1><p class="sub">Sign in to the Clarity Dental workspace.</p><form data-form="login">${field('Role account',`<select name="username">${['coordinator','dentist','reviewer','director','patient'].map(v=>`<option>${v}</option>`).join('')}</select>`)}${field('Password','<input name="password" type="password" autocomplete="current-password" required maxlength="128">')}<button>Sign in</button><button type="button" id="sample-login" class="secondary">Open sample workspace</button><p class="small">Local seeded accounts use <code>Clarity-Demo-2026!</code> unless DEMO_PASSWORD was set before the database was created. Choose an account to explore its role in the project.</p></form><div class="notice">Use coordinator to create plans and estimates, dentist for clinical approval and completion, reviewer for exceptions, director for simulated provider events, and patient for acceptance. Changing roles requires signing out.</div></section>`;}
function overview(){return title('A complete, traceable care-to-cost journey.','Persistent records, role permissions and a trained model — running together in one application.')+`<section class="hero"><h2>Clinical authority. Financial clarity.</h2><p>Create a treatment plan, obtain clinical approval, generate an estimate, record patient consent, coordinate lender workflow events, reconcile balances and track visits.</p><a class="button" href="#plans">Open treatment plans →</a></section><div class="stats">${[['CRM records',workspace.patients.length],['Treatment plans',workspace.plans.length],['Estimates',workspace.quotes.length],['Open reviews',workspace.quotes.filter(q=>q.route==='REVIEW'&&!q.disposition).length]].map(([a,b])=>`<div class="stat"><span>${a}</span><b>${b}</b></div>`).join('')}</div><div class="grid"><section class="panel"><h2>Working application scope</h2><ul class="steps"><li>16 treatment families and multi-visit care plans.</li><li>Server-side ML inference and constrained pricing.</li><li>SQLite persistence, exact balance reconciliation and decision export.</li><li>Role-specific clinical, coordinator, patient and reviewer actions.</li><li>Financing submission through sandbox settlement and refund.</li></ul></section><section class="panel"><h2>Project leadership</h2><p><h3>Andrews Mensah</h3><p>AI Product Director · Product Owner</p></p><p><p>Product strategy, requirements, architecture direction and delivery leadership.</p><a class="button secondary" href="#status">View project status</a></p><p class="small">View current adapters, data provenance and release details on the Project status page.</p></section></div>`;}
function crm(){return title('Patient relationship workspace','Patient references, contact consent and scoped access in one workspace.')+`<div class="grid"><section class="panel"><h2>CRM records</h2>${workspace.patients.map(p=>`<article class="list-item"><h3>${esc(p.reference)}</h3>${pill(p.contactConsent?'Contact consent recorded':'Contact consent absent',!p.contactConsent)}<p class="small">Version ${p.version}</p>${can('admin','coordinator','patient')?`<button data-action="consent" data-id="${p.id}">${p.contactConsent?'Withdraw':'Record'} contact consent</button>`:''}</article>`).join('')}</section>${can('admin','coordinator')?`<section class="panel"><h2>Create a patient record</h2><form data-form="patient">${field('Patient reference','<input name="reference" placeholder="Demo patient 004" pattern="Demo patient [A-Za-z0-9 -]{1,20}" maxlength="33" required>')}<button>Create CRM record</button></form><p class="small">Use the project’s sample patient references.</p></section>`:''}</div>`;}
function plans(){return title('Treatment plans and visits','A clinician approves the plan. Coordinators schedule it. Clinicians record completed visits.')+`<div class="grid">${can('admin','coordinator','clinician')?`<section class="panel"><h2>Create a plan</h2><form data-form="plan">${field('Patient',`<select name="patientId">${opts(workspace.patients,p=>p.id,p=>p.reference)}</select>`)}${field('Treatment family',`<select name="family" id="family">${opts(catalog,c=>c.code,c=>c.name)}</select>`)}${field('Chair minutes','<input name="minutes" type="number" min="15" max="180" step="1" value="45" required>')}${field('Lab cost · USD','<input name="lab" type="number" min="0" max="1500" step="1" value="0" required>')}<p id="pathway" class="small">Select a treatment for its illustrative visit count.</p><button>Create draft plan</button></form></section>`:''}<section class="panel"><h2>Care pathways</h2>${workspace.plans.length?workspace.plans.map(p=>`<article class="list-item"><h3>${esc(patient(p.patientId))} · ${esc(family(p.family))}</h3><p>${pill(p.status)}${pill(`Version ${p.version}`)}</p><p class="small">${p.minutes} chair minutes · ${money(Math.round(p.lab*100))} lab · ${catalog.find(c=>c.code===p.family)?.visits} illustrative visits</p>${p.status==='DRAFT'&&can('clinician')?`<button data-action="approve" data-id="${p.id}">Clinically approve</button>`:''}${['APPROVED','SCHEDULED'].includes(p.status)&&can('admin','coordinator','clinician')?`<form data-form="schedule" data-id="${p.id}" class="inline">${field('Next appointment','<input name="when" type="datetime-local" required>')}<button>Schedule visit</button></form>`:''}${p.appointments.map(a=>`<div class="row"><span>${esc(new Date(a.when).toLocaleString())}<br>${pill(a.status)}</span>${a.status==='SCHEDULED'&&can('clinician')?`<button data-action="complete" data-id="${p.id}" data-visit="${a.id}" ${Date.parse(a.when)>Date.now()?'disabled':''}>Complete visit</button>`:''}</div>`).join('')}${!['COMPLETED','CANCELLED'].includes(p.status)&&can('admin','coordinator','clinician')?`<button class="danger" data-action="cancel" data-id="${p.id}">Cancel pathway</button>`:''}</article>`).join(''):'<p>No plans yet. Create a draft, then sign in as dentist to approve it.</p>'}</section></div>`;}
function quotes(){const active=workspace.plans.filter(p=>['APPROVED','SCHEDULED'].includes(p.status)&&!workspace.quotes.some(q=>q.planId===p.id&&q.accepted));return title('Pricing and patient acceptance','Server-side inference, a constrained optimizer, exact money and a versioned decision record.')+`<div class="grid">${can('admin','coordinator')?`<section class="panel"><h2>Evaluate an estimate</h2>${active.length?'':'<p class="notice">No unaccepted approved plans. Create and clinically approve another plan; accepted estimates cannot be repriced.</p>'}<form data-form="quote">${field('Approved treatment plan',`<select name="planId" required>${opts(active,p=>p.id,p=>`${patient(p.patientId)} · ${family(p.family)}`)}</select>`)}${field('Benefits source',`<select name="benefits"><option value="CURRENT">Current benefits scenario</option><option value="STALE">Stale — expect blocked command</option></select>`)}${field('Deposit · USD','<input name="deposit" type="text" inputmode="decimal" value="0" required pattern="[0-9]+([.][0-9]{1,2})?">')}<label><input name="insurance" type="checkbox">Use fixed payer contract scenario</label><label><input name="loyalty" type="checkbox">Eligible single 5% loyalty benefit</label><label><input name="financing" type="checkbox">Include assumed financing expense</label><button ${active.length?'':'disabled'}>Evaluate estimate</button></form><p class="small">Benefits freshness, contract precedence and patient balances are captured with the estimate.</p></section>`:''}<section class="panel"><h2>Decision records</h2>${workspace.quotes.length?workspace.quotes.map(q=>quoteCard(q)).join(''):'<p>No estimates yet. Create and clinically approve a plan first.</p>'}</section></div>`;}
function quoteCard(q){return `<article class="list-item"><h3>${esc(patient(q.patientId))} · ${esc(family(q.input.family))}</h3><p>${pill(q.route,q.route==='REVIEW')}${pill(q.accepted?'ACCEPTED':'NOT ACCEPTED')}</p>${q.route==='ISSUED'?`<div class="total">${money(q.patient)}</div><p class="small">Estimated patient responsibility</p>${[['Treatment fee',q.net],['Estimated payer',q.payer],['Initial deposit',q.deposit],['Remaining at issue',q.balance],['Subsequent payments',q.ledger.paid],['Sandbox funding',q.ledger.funded],['Unpaid balance',q.ledger.remaining]].map(([a,b])=>`<div class="row"><span>${a}</span><strong>${money(b)}</strong></div>`).join('')}<p class="small">Cost estimate ${money(q.cost.mean)} · interval ${money(q.cost.lower)}–${money(q.cost.upper)}<br>Valid until ${esc(new Date(q.expires).toLocaleString())}</p>${!q.accepted&&can('patient','coordinator')?`<form data-form="accept" data-id="${q.id}"><label><input name="consent" type="checkbox" required>I accept this estimate.</label><button>Record estimate acceptance</button></form>`:''}${q.accepted&&q.ledger.remaining>0&&can('coordinator','admin')?`<form data-form="payment" data-id="${q.id}" class="inline">${field('Payment entry · USD','<input name="amount" type="text" inputmode="decimal" required>')}<button>Record payment</button></form>`:''}${q.accepted&&q.ledger.remaining>0&&can('coordinator','patient')&&!workspace.finance.some(f=>f.quoteId===q.id&&!['DECLINED','WITHDRAWN','REFUNDED'].includes(f.status))?`<form data-form="finance" data-id="${q.id}"><label><input name="consent" type="checkbox" required>I separately consent to a sandbox financing application.</label><button class="secondary">Submit financing application</button></form>`:''}`:`<p>${esc(q.reason)} · ${esc(q.code)}</p>${q.disposition?pill(q.disposition):can('reviewer')?`<form data-form="review" data-id="${q.id}"><select name="disposition"><option>SOURCE_REWORK</option><option>POLICY_REVIEW</option></select><button>Record review disposition</button></form>`:''}`}<button class="secondary" data-action="export" data-id="${q.id}">Export decision JSON</button><details><summary>Calculation and version evidence</summary><pre>${esc(JSON.stringify({input:q.input,model:'Clarity Cost Model 2',policy:'Pricing Policy 2',decision:q.id,version:q.version,cost:q.cost},null,2))}</pre></details></article>`;}
function finances(){return title('Financing and settlement','Track application status, separate offer consent, funding events and refunds.')+`<div class="notice">Sandbox connection · Provider events support offer, decline, funding and refund workflows. Patient or coordinator records separate offer consent.</div><section class="panel"><h2>Applications</h2>${workspace.finance.length?workspace.finance.map(f=>`<article class="list-item"><h3>${esc(patient(f.patientId))} · ${money(f.amount)}</h3><p>${pill(f.status)}${pill('Sandbox connection',true)}</p>${can('admin')&&f.status==='PENDING'?`<button data-action="provider-offer" data-id="${f.id}">Send test offer</button><button class="danger" data-action="provider-decline" data-id="${f.id}">Send test decline</button>`:''}${can('patient','coordinator')&&f.status==='OFFERED'?`<form data-form="offer" data-id="${f.id}"><label><input name="consent" type="checkbox" required>I separately accept this sandbox offer.</label><button>Accept sandbox offer</button></form>`:''}${can('admin')&&f.status==='ACCEPTED'?`<button data-action="provider-fund" data-id="${f.id}">Record sandbox funding</button>`:''}${can('admin')&&f.status==='FUNDED'?`<button class="danger" data-action="provider-refund" data-id="${f.id}">Record sandbox refund</button>`:''}${can('patient','coordinator')&&['PENDING','OFFERED','ACCEPTED'].includes(f.status)?`<button class="danger" data-action="withdraw" data-id="${f.id}">Withdraw application</button>`:''}<p class="small">Version ${f.version} · application ${esc(f.id)}</p></article>`).join(''):'<p>Accept an estimate and submit separate financing consent to begin.</p>'}</section>`;}
function evidence(){return title('AI, operations and audit evidence','Learned costs feed deterministic optimization and exact financial arithmetic.')+`<div class="grid"><section class="panel"><h2>Active model</h2><p>${pill('Clarity Cost Model · Version 2')}</p><p>${model.training_rows} training rows · ${model.calibration_rows} calibration rows · ${model.test_rows} held-out test rows.</p><p>16 treatment intercepts, chair minutes and lab cost. Review model design, evaluation methodology and data provenance on the Project status page.</p><p class="small">The training pipeline, evaluation report, reproducibility checks and CI configuration are in the source repository.</p><pre>${esc(JSON.stringify({policy:{...policy,version:'Pricing Policy 2'},intervalRadiusUSD:model.interval_radius_usd},null,2))}</pre></section><section class="panel"><h2>Operational boundaries</h2><ul class="steps"><li>SQLite retains records after server restart.</li><li>Transactions and idempotency keys prevent duplicate writes.</li><li>Role and patient scope are enforced on the server.</li><li>Audit entries form a hash chain; a privileged database owner can still alter the database.</li><li>External clinical, payer, bank and CRM vendor adapters are not connected.</li><li>Product and architecture direction: Andrews Mensah.</li></ul>${can('admin','reviewer')?'<button data-action="audit">Verify and inspect audit</button><div id="audit-output"></div>':''}</section></div>`;}
function projectStatus(){return title('Project status and leadership','Clarity Dental · Created and led by Andrews Mensah.')+`<div class="grid"><section class="panel"><h2>Andrews Mensah</h2><p><strong>AI Product Director · Product Owner</strong></p><p>Andrews defined the product vision, treatment and financing journeys, CRM requirements, architectural direction, delivery priorities and acceptance expectations. He directed the iterative design, implementation and review of the platform.</p><p>AI-assisted engineering supported implementation, documentation and testing under his direction.</p></section><section class="panel"><h2>Current operating environment</h2><div class="row"><span>Data</span><strong>Generated evaluation fixtures</strong></div><div class="row"><span>Cost model</span><strong>Trained and evaluated on generated records</strong></div><div class="row"><span>Financing adapter</span><strong>Local sandbox; funds remain simulated</strong></div><div class="row"><span>EHR, payer and vendor CRM</span><strong>External connections pending configuration</strong></div><p class="small">Aspen Dental, Synchrony and Zest AI inform the integration design. Client engagements and vendor connections are established separately. Evaluation results describe the project dataset; clinical and financial deployment requires authorized data and partner validation.</p><p class="small">Use sample records in this workspace. Source-level model identifiers and historical audit events are preserved for traceability.</p></section></div>`;}
function render(){document.querySelector('#account').innerHTML=user?`${esc(user.id)} · ${esc(user.role)} <button id="logout" class="secondary">Sign out</button>`:'';const page=['overview','crm','plans','quotes','finance','evidence','status'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';document.querySelector('#nav').innerHTML=user?['overview','crm','plans','quotes','finance','evidence','status'].map(v=>`<a href="#${v}" class="${v===page?'active':''}">${({overview:'Overview',crm:'CRM',plans:'Treatment plans',quotes:'Pricing',finance:'Financing',evidence:'AI & audit',status:'Project status'})[v]}</a>`).join(''):'';app.innerHTML=user?({overview,crm,plans,quotes,finance:finances,evidence,status:projectStatus})[page]():login();bind();}
async function refresh(){workspace=await api('/api/workspace');render();}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){toast(e.message,true);}finally{busy=false;render();}}
function bind(){
 document.querySelector('#sample-login')?.addEventListener('click',e=>{const f=e.target.form;f.elements.password.value='Clarity-Demo-2026!';f.requestSubmit();});
 document.querySelector('#logout')?.addEventListener('click',()=>run(async()=>{await api('/api/logout',{});user=null;csrf='';}));
 document.querySelector('#family')?.addEventListener('change',e=>{const c=catalog.find(c=>c.code===e.target.value),f=e.target.form;f.elements.minutes.value=c.minutes;f.elements.lab.value=c.lab;document.querySelector('#pathway').textContent=`${c.visits} illustrative visits; actual sequence and duration require clinician judgment.`;});
 document.querySelectorAll('form[data-form]').forEach(f=>f.addEventListener('submit',event=>{event.preventDefault();run(async()=>{const form=new FormData(f),b=Object.fromEntries(form),id=f.dataset.id,type=f.dataset.form;
  if(type==='login'){const s=await api('/api/login',b);user=s.user;csrf=s.csrf;const c=await api('/api/catalog');catalog=c.catalog;model=c.model;policy=c.policy;await refresh();return;}
  if(type==='patient')await api('/api/patients',b);
  if(type==='plan')await api('/api/plans',{...b,minutes:Number(b.minutes),lab:Number(b.lab)});
  if(type==='schedule'){const p=workspace.plans.find(p=>p.id===id);await api(`/api/plans/${id}/schedule`,{version:p.version,when:new Date(b.when).toISOString()});}
  if(type==='quote'){const p=workspace.plans.find(p=>p.id===b.planId);await api('/api/quotes',{planId:p.id,planVersion:p.version,benefits:b.benefits,deposit:cents(b.deposit),insurance:form.has('insurance'),loyalty:form.has('loyalty'),financing:form.has('financing')});}
  if(['accept','payment','finance','review'].includes(type)){const q=workspace.quotes.find(q=>q.id===id);await api(`/api/quotes/${id}/${type}`,{version:q.version,...(type==='payment'?{amount:cents(b.amount)}:type==='review'?{disposition:b.disposition}:{consent:form.has('consent')})});}
  if(type==='offer'){const x=workspace.finance.find(x=>x.id===id);await api(`/api/finance/${id}/accept-offer`,{version:x.version,consent:form.has('consent')});}
  await refresh();toast('Saved and recorded in the server audit trail.');});}));
 document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>run(async()=>{const {action,id,visit}=b.dataset;
  if(action==='consent'){const p=workspace.patients.find(p=>p.id===id);await api(`/api/patients/${id}/consent`,{version:p.version,consent:!p.contactConsent});}
  if(['approve','cancel','complete'].includes(action)){const p=workspace.plans.find(p=>p.id===id);await api(`/api/plans/${id}/${action==='complete'?'complete-visit':action}`,{version:p.version,...(visit?{appointmentId:visit}:{})});}
  if(action.startsWith('provider-')||action==='withdraw'){const x=workspace.finance.find(x=>x.id===id);await api(`/api/finance/${id}/${action==='withdraw'?'withdraw':'provider-event'}`,{version:x.version,...(action==='withdraw'?{}:{source:'local-simulator',event:action.slice(9)})});}
  if(action==='export'){const data=await api(`/api/quotes/${id}/export`),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`clarity-quote-${id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  if(action==='audit'){const data=await api('/api/audit');window.auditData=data;return;}
  await refresh();toast('Action saved.');})));}
window.addEventListener('hashchange',render);
async function start(){try{const s=await api('/api/session');user=s.user;csrf=s.csrf;const c=await api('/api/catalog');catalog=c.catalog;model=c.model;policy=c.policy;workspace=await api('/api/workspace');}catch(e){if(user)toast(e.message,true);}render();}
// Audit data is rendered as escaped text after asynchronous actions complete.
const baseRender=render;
render=function(){baseRender();if(window.auditData&&location.hash==='#evidence'&&can('admin','reviewer'))document.querySelector('#audit-output').innerHTML=`<p>${pill(window.auditData.verified?'Hash chain verified':'Integrity check failed',!window.auditData.verified)}</p><pre>${esc(JSON.stringify(window.auditData.events.map(e=>({sequence:e.seq,time:e.time,actor:e.actor,activity:e.action.replace('SYNTHETIC_',''),record:e.entity,digest:e.digest})),null,2))}</pre>`;};
start();
